CREATE TABLE public.follows (follower_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, following_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(follower_id, following_id), CHECK(follower_id <> following_id));
GRANT SELECT, INSERT, DELETE ON public.follows TO authenticated;
GRANT ALL ON public.follows TO service_role;
ALTER TABLE public.follows ENABLE ROW LEVEL SECURITY;
CREATE POLICY "follows signed in read" ON public.follows FOR SELECT TO authenticated USING (auth.uid() IS NOT NULL);
CREATE POLICY "follows own insert" ON public.follows FOR INSERT TO authenticated WITH CHECK(auth.uid() = follower_id);
CREATE POLICY "follows own delete" ON public.follows FOR DELETE TO authenticated USING(auth.uid() = follower_id);
CREATE INDEX follows_target_idx ON public.follows(following_id);
CREATE TABLE public.account_verifications (user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE, verified_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.account_verifications TO authenticated;
GRANT ALL ON public.account_verifications TO service_role;
ALTER TABLE public.account_verifications ENABLE ROW LEVEL SECURITY;
CREATE POLICY "verified signed in read" ON public.account_verifications FOR SELECT TO authenticated USING(auth.uid() IS NOT NULL);
CREATE TABLE public.verification_requests (user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE, reason text NOT NULL CHECK(char_length(reason) BETWEEN 10 AND 1000), status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT ON public.verification_requests TO authenticated;
GRANT ALL ON public.verification_requests TO service_role;
ALTER TABLE public.verification_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY "verification own read" ON public.verification_requests FOR SELECT TO authenticated USING(auth.uid() = user_id);
CREATE POLICY "verification request own" ON public.verification_requests FOR INSERT TO authenticated WITH CHECK(auth.uid() = user_id AND status = 'pending');